<span class="list-progress-sort"><span>Avancement</span><?php foreach(['asc'=>'up','desc'=>'down'] as $progressDirection=>$progressIcon): $progressActive=($filters['sort']??'')==='progress_percent' && ($filters['direction']??'asc')===$progressDirection; ?><a href="<?= e(query_url('/'.$section,$baseQuery,['sort'=>'progress_percent','direction'=>$progressDirection,'page'=>1])) ?>" class="<?= $progressActive?'selected':'' ?>" aria-label="<?= $progressDirection==='asc'?'Trier par avancement croissant':'Trier par avancement décroissant' ?>" title="<?= $progressDirection==='asc'?'Avancement croissant':'Avancement décroissant' ?>" <?= $progressActive?'aria-current="true"':'' ?>><?= icon($progressIcon) ?></a><?php endforeach; ?></span>
